<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>DeployCloud Blog — Discover the latest in web development</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --primary: #171717;
      --accent: #0072F5;
      --accent-hover: #0060D6;
      --bg: #FAFAFA;
      --bg-white: #FFFFFF;
      --border: #E5E5E5;
      --border-light: #F0F0F0;
      --text-primary: #171717;
      --text-secondary: #525252;
      --text-muted: #737373;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.06);
      --shadow-lg: 0 8px 30px rgba(0,0,0,0.08);
      --radius-sm: 6px;
      --radius-md: 10px;
      --radius-lg: 14px;
      --radius-full: 9999px;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      background: var(--bg);
      color: var(--text-primary);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }

    /* ===== HEADER ===== */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
    }
    .header-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
      height: 64px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .header-left { display: flex; align-items: center; gap: 32px; }
    .logo {
      font-weight: 800;
      font-size: 18px;
      display: flex;
      align-items: center;
      gap: 8px;
      letter-spacing: -0.02em;
    }
    .logo-icon {
      width: 28px;
      height: 28px;
      background: var(--accent);
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .logo-icon svg { width: 16px; height: 16px; }
    .nav-links { display: flex; align-items: center; gap: 4px; }
    .nav-item {
      position: relative;
      padding: 8px 14px;
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      border-radius: var(--radius-sm);
      transition: color 0.15s, background 0.15s;
      display: flex;
      align-items: center;
      gap: 4px;
    }
    .nav-item:hover { color: var(--text-primary); background: var(--border-light); }
    .nav-item svg { width: 14px; height: 14px; transition: transform 0.2s; }
    .nav-item.open svg { transform: rotate(180deg); }
    .header-right { display: flex; align-items: center; gap: 12px; }
    .ask-ai-btn {
      display: flex;
      align-items: center;
      gap: 6px;
      padding: 7px 14px;
      font-size: 13px;
      font-weight: 500;
      color: var(--accent);
      border: 1px solid var(--accent);
      border-radius: var(--radius-full);
      transition: all 0.15s;
    }
    .ask-ai-btn:hover { background: var(--accent); color: #fff; }
    .ask-ai-btn svg { width: 14px; height: 14px; }
    .login-btn {
      padding: 7px 16px;
      font-size: 13px;
      font-weight: 500;
      color: var(--text-secondary);
      transition: color 0.15s;
    }
    .login-btn:hover { color: var(--text-primary); }
    .signup-btn {
      padding: 7px 18px;
      font-size: 13px;
      font-weight: 600;
      color: #fff;
      background: var(--primary);
      border-radius: var(--radius-full);
      transition: background 0.15s;
    }
    .signup-btn:hover { background: #333; }

    /* ===== MEGA MENU ===== */
    .mega-menu {
      position: absolute;
      top: 100%;
      left: 50%;
      transform: translateX(-50%);
      background: var(--bg-white);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg);
      padding: 24px;
      opacity: 0;
      visibility: hidden;
      pointer-events: none;
      transition: opacity 0.2s, transform 0.2s;
      transform: translateX(-50%) translateY(8px);
      min-width: 640px;
    }
    .mega-menu.active {
      opacity: 1;
      visibility: visible;
      pointer-events: auto;
      transform: translateX(-50%) translateY(0);
    }
    .mega-menu-grid {
      display: grid;
      grid-template-columns: 1fr 1fr 1fr;
      gap: 24px;
    }
    .mega-col-title {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--text-muted);
      margin-bottom: 12px;
    }
    .mega-item {
      display: flex;
      flex-direction: column;
      padding: 8px 0;
    }
    .mega-item-name {
      font-size: 14px;
      font-weight: 600;
      color: var(--text-primary);
      margin-bottom: 2px;
    }
    .mega-item-desc {
      font-size: 12px;
      color: var(--text-muted);
      line-height: 1.4;
    }
    .mega-item:hover .mega-item-name { color: var(--accent); }

    .resources-menu { min-width: 420px; }
    .resources-menu .mega-menu-grid { grid-template-columns: 1fr 1fr 1fr; gap: 20px; }
    .resources-menu .mega-item-name { font-weight: 500; font-size: 13px; }
    .mega-link-list { display: flex; flex-direction: column; gap: 2px; }
    .mega-link {
      font-size: 13px;
      font-weight: 500;
      color: var(--text-secondary);
      padding: 5px 0;
      transition: color 0.15s;
    }
    .mega-link:hover { color: var(--accent); }

    /* ===== CATEGORY FILTERS ===== */
    .filters-section {
      background: var(--bg-white);
      border-bottom: 1px solid var(--border);
    }
    .filters-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 20px 24px;
      display: flex;
      align-items: center;
      gap: 16px;
      flex-wrap: wrap;
    }
    .category-pills {
      display: flex;
      gap: 6px;
      flex-wrap: wrap;
      flex: 1;
    }
    .pill {
      padding: 7px 16px;
      font-size: 13px;
      font-weight: 500;
      color: var(--text-secondary);
      border: 1px solid var(--border);
      border-radius: var(--radius-full);
      background: var(--bg-white);
      transition: all 0.15s;
      white-space: nowrap;
    }
    .pill:hover { border-color: var(--text-muted); color: var(--text-primary); }
    .pill.active {
      background: var(--primary);
      color: #fff;
      border-color: var(--primary);
    }
    .search-box {
      position: relative;
      flex-shrink: 0;
    }
    .search-box input {
      width: 220px;
      padding: 8px 14px 8px 36px;
      font-size: 13px;
      font-family: inherit;
      border: 1px solid var(--border);
      border-radius: var(--radius-full);
      background: var(--bg);
      color: var(--text-primary);
      outline: none;
      transition: border-color 0.15s, box-shadow 0.15s;
    }
    .search-box input::placeholder { color: var(--text-muted); }
    .search-box input:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 3px rgba(0,114,245,0.1);
    }
    .search-box svg {
      position: absolute;
      left: 12px;
      top: 50%;
      transform: translateY(-50%);
      width: 16px;
      height: 16px;
      color: var(--text-muted);
    }

    /* ===== FEATURED ARTICLES ===== */
    .featured-section {
      max-width: 1280px;
      margin: 0 auto;
      padding: 48px 24px 32px;
    }
    .section-label {
      font-size: 12px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--text-muted);
      margin-bottom: 24px;
    }
    .featured-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 20px;
    }
    .featured-card {
      background: var(--bg-white);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 28px;
      transition: box-shadow 0.2s, transform 0.2s, border-color 0.2s;
      display: flex;
      flex-direction: column;
      position: relative;
      overflow: hidden;
    }
    .featured-card:hover {
      box-shadow: var(--shadow-lg);
      transform: translateY(-2px);
      border-color: transparent;
    }
    .featured-card.primary {
      grid-row: span 2;
      padding: 36px;
      background: linear-gradient(135deg, #0a0f1a 0%, #0d1b2a 100%);
      border: none;
      color: #fff;
    }
    .featured-card.primary:hover { box-shadow: 0 12px 40px rgba(0,0,0,0.2); }
    .featured-card .card-category {
      display: inline-block;
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      padding: 4px 10px;
      border-radius: var(--radius-full);
      background: rgba(0,114,245,0.1);
      color: var(--accent);
      margin-bottom: 16px;
      width: fit-content;
    }
    .featured-card.primary .card-category {
      background: rgba(0,114,245,0.2);
      color: #5cb8ff;
    }
    .featured-card .card-date {
      font-size: 13px;
      color: var(--text-muted);
      margin-bottom: 10px;
    }
    .featured-card.primary .card-date { color: rgba(255,255,255,0.6); }
    .featured-card .card-title {
      font-size: 22px;
      font-weight: 700;
      line-height: 1.3;
      margin-bottom: 12px;
      letter-spacing: -0.01em;
    }
    .featured-card.primary .card-title { font-size: 30px; letter-spacing: -0.02em; }
    .featured-card .card-excerpt {
      font-size: 15px;
      line-height: 1.65;
      color: var(--text-secondary);
      flex: 1;
    }
    .featured-card.primary .card-excerpt { color: rgba(255,255,255,0.7); }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
      margin-top: 24px;
      padding-top: 24px;
      border-top: 1px solid rgba(255,255,255,0.1);
    }
    .stat-item { text-align: left; }
    .stat-value {
      font-size: 26px;
      font-weight: 800;
      color: #5cb8ff;
      line-height: 1.2;
      letter-spacing: -0.02em;
    }
    .stat-label {
      font-size: 12px;
      color: rgba(255,255,255,0.5);
      line-height: 1.3;
      margin-top: 2px;
    }
    .featured-card .card-author {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-top: 20px;
      padding-top: 16px;
      border-top: 1px solid var(--border-light);
    }
    .featured-card.primary .card-author { border-top-color: rgba(255,255,255,0.1); }
    .author-avatar {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: var(--accent);
      display: flex;
      align-items: center;
      justify-content: center;
      color: #fff;
      font-size: 13px;
      font-weight: 600;
      flex-shrink: 0;
    }
    .featured-card.primary .author-avatar { background: rgba(255,255,255,0.15); }
    .author-name {
      font-size: 13px;
      font-weight: 600;
    }
    .featured-card.primary .author-name { color: rgba(255,255,255,0.9); }

    /* ===== LATEST NEWS ===== */
    .latest-section {
      max-width: 1280px;
      margin: 0 auto;
      padding: 16px 24px 48px;
    }
    .latest-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }
    .post-card {
      background: var(--bg-white);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: 24px;
      transition: box-shadow 0.2s, transform 0.2s, border-color 0.2s;
      display: flex;
      flex-direction: column;
    }
    .post-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-1px);
      border-color: transparent;
    }
    .post-card .card-category {
      display: inline-block;
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      padding: 3px 8px;
      border-radius: var(--radius-full);
      background: rgba(0,114,245,0.08);
      color: var(--accent);
      margin-bottom: 12px;
      width: fit-content;
    }
    .post-card .card-date {
      font-size: 12px;
      color: var(--text-muted);
      margin-bottom: 8px;
    }
    .post-card .card-title {
      font-size: 16px;
      font-weight: 700;
      line-height: 1.35;
      margin-bottom: 8px;
      letter-spacing: -0.01em;
    }
    .post-card .card-excerpt {
      font-size: 13px;
      line-height: 1.55;
      color: var(--text-secondary);
      flex: 1;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }
    .post-card .card-author {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-top: 16px;
      padding-top: 14px;
      border-top: 1px solid var(--border-light);
    }
    .post-card .author-avatar {
      width: 26px;
      height: 26px;
      font-size: 11px;
    }
    .post-card .author-name { font-size: 12px; font-weight: 500; color: var(--text-secondary); }

    .show-more-wrap {
      text-align: center;
      margin-top: 32px;
    }
    .show-more-btn {
      padding: 12px 32px;
      font-size: 14px;
      font-weight: 600;
      color: var(--text-primary);
      border: 1px solid var(--border);
      border-radius: var(--radius-full);
      background: var(--bg-white);
      transition: all 0.15s;
    }
    .show-more-btn:hover {
      border-color: var(--text-primary);
      box-shadow: var(--shadow-sm);
    }

    /* ===== NO RESULTS ===== */
    .no-results {
      text-align: center;
      padding: 64px 24px;
      display: none;
    }
    .no-results.visible { display: block; }
    .no-results svg { width: 48px; height: 48px; color: var(--text-muted); margin-bottom: 16px; }
    .no-results-title { font-size: 18px; font-weight: 600; margin-bottom: 8px; }
    .no-results-text { font-size: 14px; color: var(--text-muted); max-width: 400px; margin: 0 auto; }

    /* ===== CTA BANNER ===== */
    .cta-section {
      background: var(--primary);
      color: #fff;
    }
    .cta-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 64px 24px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      align-items: center;
    }
    .cta-block h2 {
      font-size: 28px;
      font-weight: 800;
      line-height: 1.25;
      margin-bottom: 16px;
      letter-spacing: -0.02em;
    }
    .cta-block h2 em {
      font-style: normal;
      color: var(--accent);
    }
    .cta-block p {
      font-size: 15px;
      color: rgba(255,255,255,0.6);
      margin-bottom: 24px;
      line-height: 1.5;
    }
    .cta-buttons { display: flex; gap: 12px; flex-wrap: wrap; }
    .btn-primary {
      padding: 11px 24px;
      font-size: 14px;
      font-weight: 600;
      color: var(--primary);
      background: #fff;
      border-radius: var(--radius-full);
      transition: background 0.15s;
    }
    .btn-primary:hover { background: #e5e5e5; }
    .btn-secondary {
      padding: 11px 24px;
      font-size: 14px;
      font-weight: 600;
      color: #fff;
      border: 1px solid rgba(255,255,255,0.25);
      border-radius: var(--radius-full);
      transition: all 0.15s;
    }
    .btn-secondary:hover { border-color: rgba(255,255,255,0.5); background: rgba(255,255,255,0.05); }

    /* ===== FOOTER ===== */
    .footer {
      background: #0a0a0a;
      color: rgba(255,255,255,0.7);
    }
    .footer-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 48px 24px 24px;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 32px;
      margin-bottom: 48px;
    }
    .footer-col-title {
      font-size: 12px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: rgba(255,255,255,0.4);
      margin-bottom: 14px;
    }
    .footer-links { display: flex; flex-direction: column; gap: 6px; }
    .footer-link {
      font-size: 13px;
      color: rgba(255,255,255,0.6);
      transition: color 0.15s;
    }
    .footer-link:hover { color: #fff; }
    .footer-bottom {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-top: 24px;
      border-top: 1px solid rgba(255,255,255,0.08);
    }
    .footer-status {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 12px;
      color: rgba(255,255,255,0.4);
    }
    .status-dot {
      width: 8px;
      height: 8px;
      background: #10b981;
      border-radius: 50%;
    }
    .footer-copy { font-size: 12px; color: rgba(255,255,255,0.3); }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 1024px) {
      .featured-grid { grid-template-columns: 1fr; }
      .featured-card.primary { grid-row: span 1; }
      .latest-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: repeat(3, 1fr); }
      .mega-menu { min-width: 480px; }
      .mega-menu-grid { grid-template-columns: 1fr 1fr; }
    }
    @media (max-width: 768px) {
      .nav-links { display: none; }
      .header-right .login-btn { display: none; }
      .latest-grid { grid-template-columns: 1fr; }
      .cta-inner { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
      .filters-inner { flex-direction: column; align-items: stretch; }
      .search-box input { width: 100%; }
      .featured-card .card-title { font-size: 18px; }
      .featured-card.primary .card-title { font-size: 24px; }
      .stats-grid { grid-template-columns: 1fr; }
      .mega-menu { min-width: 300px; }
      .mega-menu-grid { grid-template-columns: 1fr; }
    }
    @media (max-width: 480px) {
      .footer-grid { grid-template-columns: 1fr; }
      .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }
    }

    /* ===== ANIMATION ===== */
    @keyframes fadeIn {
      from { opacity: 0; transform: translateY(8px); }
      to { opacity: 1; transform: translateY(0); }
    }
    .post-card, .featured-card {
      animation: fadeIn 0.3s ease-out;
    }
    .post-card.hidden, .featured-card.hidden {
      display: none;
    }
  </style>
</head>
